journal_kable <- function(
    ..., wide = FALSE, hold = FALSE, font_size = 7, widths = NULL) {
  output <- knitr::kable(...)
  if (knitr::is_latex_output()) {
    latex_options <- "scale_down"
    if (hold) {
      latex_options <- c(latex_options, "hold_position")
    }
    output <- kableExtra::kable_styling(
      output,
      latex_options = latex_options,
      font_size = font_size
    )
    # Fixed widths wrap long text columns instead of shrinking the table.
    for (i in which(!is.na(widths))) {
      output <- kableExtra::column_spec(output, i, width = widths[[i]])
    }
    if (wide) {
      output <- sub("\\begin{table}", "\\begin{table*}", output, fixed = TRUE)
      output <- sub("\\end{table}", "\\end{table*}", output, fixed = TRUE)
    }
  }
  output
}

