draw_box <- function(x, y, width, height, label, fill, border = "#3f4f5f") {
  rect(
    x - width / 2, y - height / 2,
    x + width / 2, y + height / 2,
    col = fill, border = border, lwd = 1.2
  )
  text(x, y, label, cex = 0.83)
}

draw_arrow <- function(x0, y0, x1, y1) {
  arrows(x0, y0, x1, y1, length = 0.07, lwd = 1.1, col = "#526779")
}

