## ----expansion-mesh-shift, echo=FALSE, out.width="100%", fig.cap="Difference in MeSH descriptor prevalence between citation-discovered candidates and the title-defined seed corpus. Positive values indicate higher prevalence among candidates; negative values indicate higher prevalence among seeds.", fig.alt=if (knitr::is_html_output()) "A horizontal bar chart showing differences in MeSH descriptor prevalence between citation-discovered candidates and seed articles." else NULL----
seed_pmids <- snowball |>
  filter(seed) |>
  pull(pmid)
candidate_pmids <- snowball |>
  filter(!seed) |>
  pull(pmid)

seed_profile <- expansion_metadata |>
  filter(pmid %in% seed_pmids) |>
  puremoe::mesh_keyness(min_count = 1L)
candidate_profile <- expansion_metadata |>
  filter(pmid %in% candidate_pmids) |>
  puremoe::mesh_keyness(min_count = 1L)

profile_shift <- full_join(
  seed_profile |>
    transmute(DescriptorUI, DescriptorName, seed_prop = corpus_prop),
  candidate_profile |>
    transmute(
      DescriptorUI,
      candidate_name = DescriptorName,
      candidate_prop = corpus_prop
    ),
  by = "DescriptorUI"
) |>
  mutate(
    DescriptorName = coalesce(DescriptorName, candidate_name),
    seed_prop = replace_na(seed_prop, 0),
    candidate_prop = replace_na(candidate_prop, 0),
    change_pp = 100 * (candidate_prop - seed_prop)
  )

plot_shift <- profile_shift |>
  arrange(desc(abs(change_pp))) |>
  slice_head(n = 12L)

ggplot(
  plot_shift,
  aes(x = reorder(DescriptorName, change_pp), y = change_pp,
      fill = change_pp > 0)
) +
  geom_col(show.legend = FALSE) +
  geom_hline(yintercept = 0, colour = "grey35", linewidth = 0.3) +
  coord_flip() +
  scale_fill_manual(values = c(`TRUE` = "#2774AE", `FALSE` = "#B7352D")) +
  labs(
    x = NULL,
    y = "Candidate minus seed prevalence (percentage points)",
    title = "How citation expansion changes the MeSH profile"
  ) +
  theme_minimal(base_size = 11)


