## ----pubtator-context---------------------------------------------------------
context <- puremoe::pubtator_context(pubtator)
cooccurrence_types <- puremoe::pubtator_cooccurrence(
  context,
  window = 0L,
  by = "type"
)


## ----pubtator-concept-labels, echo=FALSE--------------------------------------
mesh_labels <- mesh_thesaurus |>
  transmute(
    mesh_ui = as.character(DescriptorUI),
    mesh_name = as.character(DescriptorName)
  ) |>
  distinct()

concept_entities <- context$entities |>
  mutate(
    attested_text = text,
    mesh_ui = sub("^MESH:", "", identifier),
    mesh_ui = if_else(
      !is.na(identifier) & grepl("^[CD][0-9]+$", mesh_ui),
      mesh_ui,
      NA_character_
    )
  ) |>
  left_join(mesh_labels, by = "mesh_ui") |>
  mutate(
    identifier = if_else(
      !is.na(mesh_name),
      paste0("MESH:", mesh_ui),
      identifier
    ),
    text = coalesce(mesh_name, text)
  )


## ----pubtator-concept-cooccurrence--------------------------------------------
cooccurrence_concepts <- puremoe::pubtator_cooccurrence(
  concept_entities,
  window = 0L,
  by = "entity"
)


## ----pubtator-context-table, echo=FALSE---------------------------------------
attested_forms <- concept_entities |>
  filter(!is.na(sentence_id), !is.na(text), nzchar(text)) |>
  count(type, identifier, text, attested_text, name = "form_n") |>
  arrange(type, identifier, text, desc(form_n), attested_text) |>
  group_by(type, identifier, text) |>
  slice_head(n = 3L) |>
  summarise(
    attested = paste(attested_text, collapse = "; "),
    .groups = "drop"
  )

forms_x <- attested_forms |>
  rename(
    type_x = type,
    identifier_x = identifier,
    text_x = text,
    attested_x = attested
  )
forms_y <- attested_forms |>
  rename(
    type_y = type,
    identifier_y = identifier,
    text_y = text,
    attested_y = attested
  )

cooccurrence_display <- cooccurrence_concepts |>
  left_join(forms_x, by = c("type_x", "identifier_x", "text_x")) |>
  left_join(forms_y, by = c("type_y", "identifier_y", "text_y")) |>
  mutate(
    concept_x = if_else(
      !is.na(identifier_x) & grepl("^MESH:", identifier_x),
      paste0(text_x, " [", sub("^MESH:", "", identifier_x), "]"),
      text_x
    ),
    concept_y = if_else(
      !is.na(identifier_y) & grepl("^MESH:", identifier_y),
      paste0(text_y, " [", sub("^MESH:", "", identifier_y), "]"),
      text_y
    )
  ) |>
  slice_head(n = 12L) |>
  select(type_x, concept_x, attested_x, type_y, concept_y, attested_y, n, n_pmids)

cooccurrence_display |>
  journal_kable(caption = paste(
    "Most frequent same-sentence entity pairs after MeSH label resolution.",
    "Bracketed values are MeSH UIs; attested columns retain source forms."
  ), wide = TRUE, hold = TRUE, font_size = 7,
  widths = c("1.1cm", "2.2cm", "1.8cm", "1.1cm", "2.2cm", "1.8cm", NA, NA))


