## ----pubtator-network-evidence, echo=FALSE------------------------------------
relation_mentions <- context$relations |>
  transmute(
    pmid = as.character(pmid),
    relation_id = as.character(relation_id),
    from_mention = ent1_text,
    to_mention = ent2_text
  ) |>
  distinct()

same_sentence_evidence <- relation_net$evidence |>
  filter(same_sentence %in% TRUE, !is.na(sentence), nzchar(sentence)) |>
  left_join(
    network_nodes |>
      transmute(from = id, from_concept = concept),
    by = "from"
  ) |>
  left_join(
    network_nodes |>
      transmute(to = id, to_concept = concept),
    by = "to"
  ) |>
  left_join(relation_mentions, by = c("pmid", "relation_id"))

same_sentence_evidence |>
  slice_head(n = 8L) |>
  transmute(
    from_concept,
    from_mention,
    to_concept,
    to_mention,
    relation_type = if (knitr::is_latex_output()) {
      gsub("_", " ", relation_type)
    } else {
      relation_type
    },
    pmid,
    sentence = paste0(
      substr(sentence, 1L, if (knitr::is_latex_output()) 100L else 180L),
      "..."
    )
  ) |>
  journal_kable(caption = paste(
