## ----pubtator-focal-network, echo=FALSE, fig.width=10, fig.height=7.2, out.width="100%", fig.cap="Supported PubTator3 relation neighborhood around buprenorphine and opioid use disorder (OUD). Nodes are entities and colors distinguish entity types; node size increases with the number of supporting PMIDs. Node labels are the most frequent PubTator3 surface form for each concept, whereas Tables 8 and 9 use MeSH preferred names. Edges are same-sentence PubTator3 relations supported by at least two distinct PMIDs; color and line type distinguish relation classes, and width increases with article support. Species entities are excluded. The display summarizes upstream model predictions and should not be interpreted as a validated biomedical or causal network.", fig.alt=if (knitr::is_html_output()) "A network centered on buprenorphine and opioid use disorder. Chemical entities are blue-green, disease entities are red, and colored solid or dashed edges show types of same-sentence PubTator3 relations supported by at least two articles." else NULL----
nodes <- data.table::copy(relation_net$nodes)
excluded_ids <- nodes[type == "Species", id]
focal_evidence <- data.table::copy(relation_net$evidence)[
  same_sentence %in% TRUE &
    !is.na(from) & !is.na(to) &
    from != to &
    !from %in% excluded_ids & !to %in% excluded_ids
]

focal_edges <- focal_evidence[, .(
  weight = .N,
  n_pmids = data.table::uniqueN(pmid),
  n_sentences = data.table::uniqueN(paste(pmid, sentence, sep = "\r"))
), by = .(from, to, relation_type)][
  order(-n_pmids, -n_sentences, -weight, relation_type, from, to)
]

anchor_nodes <- data.table::rbindlist(lapply(c("buprenorphine", "oud"), function(x) {
  nodes[tolower(label) == x][order(-n_pmids, -n_mentions, id)][1L]
}))
anchor_ids <- anchor_nodes$id
stopifnot(nrow(anchor_nodes) == 2L, !anyNA(anchor_ids))

anchor_edges <- focal_edges[
  (from %in% anchor_ids | to %in% anchor_ids) & n_pmids >= 2L
]
neighbor_ids <- setdiff(unique(c(anchor_edges$from, anchor_edges$to)), anchor_ids)
neighbor_edges <- focal_edges[
  from %in% neighbor_ids & to %in% neighbor_ids & n_pmids >= 2L
]
plot_edges <- unique(
  data.table::rbindlist(list(anchor_edges, neighbor_edges), use.names = TRUE),
  by = c("from", "to", "relation_type")
)[order(-n_pmids, -n_sentences, -weight, relation_type, from, to)]

selected_ids <- unique(c(anchor_ids, plot_edges$from, plot_edges$to))
plot_nodes <- nodes[id %in% selected_ids]
layout_graph <- graph_from_data_frame(
  unique(plot_edges[, .(from, to)]),
  directed = FALSE,
  vertices = plot_nodes
)

set.seed(47)
xy <- layout_with_fr(layout_graph, niter = 1500L)
plot_nodes <- merge(
  plot_nodes,
  data.table::data.table(id = V(layout_graph)$name, x = xy[, 1], y = xy[, 2]),
  by = "id", all.x = TRUE, sort = FALSE
)
plot_edges <- merge(
  plot_edges,
  plot_nodes[, .(from = id, x, y)],
  by = "from", all.x = TRUE, sort = FALSE
)
plot_edges <- merge(
  plot_edges,
  plot_nodes[, .(to = id, xend = x, yend = y)],
  by = "to", all.x = TRUE, sort = FALSE
)

node_palette <- c(Chemical = "#4F7C82", Disease = "#B76558", Gene = "#6D8A59",
                  Mutation = "#B08A4E", CellLine = "#717D82")
