  negative_correlation = "solid", positive_correlation = "solid"
)
relation_types <- sort(unique(plot_edges$relation_type))
relation_labels <- setNames(
  tools::toTitleCase(gsub("_", " ", relation_types)),
  relation_types
)

network_plot <- ggplot() +
  geom_curve(
    data = plot_edges,
    aes(x = x, y = y, xend = xend, yend = yend,
        colour = relation_type, linetype = relation_type,
        linewidth = log1p(n_pmids), alpha = log1p(n_pmids)),
    curvature = 0.10, lineend = "round"
  ) +
  geom_point(
    data = plot_nodes,
    aes(x = x, y = y, fill = type, size = log1p(n_pmids)),
    shape = 21, colour = "white", stroke = 0.8
  ) +
  geom_label_repel(
    data = plot_nodes,
    aes(x = x, y = y, label = label),
    size = 3.1, colour = "#292D2F", fill = scales::alpha("white", 0.88),
    label.size = 0, label.padding = grid::unit(0.10, "lines"),
    label.r = grid::unit(0.08, "lines"), box.padding = 0.30,
    point.padding = 0.15, min.segment.length = 0,
    segment.colour = scales::alpha("#60676A", 0.50),
    segment.size = 0.3, max.overlaps = Inf, seed = 47
  ) +
  scale_colour_manual(
    name = "Relation", values = relation_palette,
    breaks = relation_types, labels = relation_labels
  ) +
  scale_linetype_manual(
    name = "Relation", values = relation_linetypes,
    breaks = relation_types, labels = relation_labels
  ) +
  scale_fill_manual(name = "Entity", values = node_palette, na.value = "#777F82") +
  scale_linewidth_continuous(range = c(0.60, 2.2), guide = "none") +
  scale_alpha_continuous(range = c(0.38, 0.82), guide = "none") +
  scale_size_continuous(range = c(4.0, 9.0), guide = "none") +
  coord_equal(clip = "off") +
  guides(
    colour = guide_legend(
      order = 1, nrow = 2,
      override.aes = list(linewidth = 1.5, alpha = 0.90)
    ),
    linetype = "none",
    fill = guide_legend(order = 2, nrow = 1, override.aes = list(size = 4.5))
  ) +
  theme_void(base_size = 11) +
  theme(
    legend.position = "bottom", legend.box = "vertical",
    legend.justification = "center",
    legend.title = element_text(face = "bold", colour = "#353A3C"),
    legend.text = element_text(colour = "#454B4E"),
    legend.spacing.y = grid::unit(0.05, "lines"),
    plot.margin = margin(20, 28, 12, 28)
  )

network_plot


