## ----pmc-fulltext-table, echo=FALSE-------------------------------------------
if (nrow(fulltext)) {
  fulltext_display <- fulltext[
    !is.na(text) & nzchar(text),
    .SD[{
      preferred <- grep("abstract|introduction", section, ignore.case = TRUE)
      if (length(preferred)) preferred[1L] else 1L
    }],
    by = pmid
  ][seq_len(min(.N, 3L))]

  fulltext_display[, text := trimws(gsub("[[:space:]]+", " ", text))]
  fulltext_display[, text := trimws(sub(
    "^[[:digit:].[:space:]]*(Abstract|Introduction)[[:space:]]*",
    "",
    text,
    ignore.case = TRUE
  ))]
  fulltext_display[, text := ifelse(
    nchar(text) > 180L,
    paste0(substr(text, 1L, 180L), "\u2026"),
    text
  )]

  fulltext_display[, .(pmid, section, text)] |>
    journal_kable(
      caption = "Representative section text from each retrieved PMC article.",
      wide = TRUE,
      hold = TRUE,
      font_size = 8,
      widths = c("1.4cm", "1.8cm", "9.4cm")
    )
}


## ----reproducibility-record, echo=FALSE---------------------------------------
reproducibility_record <- tibble::tibble(
  Item = c(
    "Retrieval date", "puremoe version (retrieval)",
    "puremoe version (render; CRAN)", "R version", "Platform",
    "Retrieval workers", "NCBI API key used"
  ),
  Value = c(
    format(snapshot_metadata$retrieval_date, "%Y-%m-%d"),
    snapshot_metadata$puremoe_version,
    as.character(utils::packageVersion("puremoe")),
    snapshot_metadata$r_version,
    snapshot_metadata$platform,
    as.character(snapshot_metadata$cores),
    if (isTRUE(snapshot_metadata$ncbi_api_key_used)) "Yes" else "No"
  )
)
journal_kable(
  reproducibility_record,
  caption = "Environment and retrieval settings for the archived article snapshot.",
  hold = TRUE
)

